// Writes an intent locally. This command never sends a request.
import { open, readFile } from 'node:fs/promises';
import { basename } from 'node:path';
import { randomUUID } from 'node:crypto';
import { requestOptions } from './quest.ts';
const [action, output, identity, file, media] = process.argv.slice(2);
const operation = randomUUID();
const intent = { base_url: process.env.FOREVERLEARNING_BASE_URL ?? 'https://developers-api-staging.foreverlearning.ai/v1',
  assignment_id: process.env.FOREVERLEARNING_ASSIGNMENT_ID ?? '<your-assignment-id>',
  external_user_id: process.env.FOREVERLEARNING_USER_ID ?? 'synthetic-learner-1', method: 'GET', path: '' };
const prompts = { guided: 'Help me reason about why 3/4 is greater than 2/3. Ask me for a first step.',
  feedback: 'My work says 3/4 = 6/8 and 2/3 = 6/9, so 2/3 is larger because 9 is larger. Help me check that reasoning.',
  explain: 'Explain this supplied solution: 3/4 = 9/12 and 2/3 = 8/12, so 3/4 is larger.',
  default: 'Continue with a question that helps me try the next step.' };
if (Object.hasOwn(prompts, action) || action === 'opening') {
  intent.method = 'POST'; intent.path = '/chat';
  intent.body = { session_id: identity, prompt: action === 'opening' ? '' : prompts[action],
    ...(action === 'default' ? {} : { posture: action === 'opening' ? 'guided' : action }),
    quest: { operation: action === 'opening' ? 'opening' : 'turn', requested_support: 'auto', team_dialog: false,
      ...(file ? { attachment_ids: file.split(',') } : {}) } };
} else if (action === 'setup') {
  intent.method = 'POST'; intent.path = '/quest/sessions'; intent.body = { setup: { task: { kind: 'practice', subject: 'Fractions', assignment: 'Compare fractions using equivalent denominators.' },
    learner: { preferred_name: 'Sample learner', grade_band: 'middle', language: 'en', reading_level: 'on_grade', support_needs: 'none' }, team_dialog: false } };
} else if (action === 'upload') {
  const bytes = await readFile(file);
  if (!['image/png', 'image/jpeg', 'image/webp', 'text/plain', 'text/markdown'].includes(media)
    || !bytes.length || bytes.length > (media.startsWith('image/') ? 8 * 1024 * 1024 : 64 * 1024)) throw new Error('Unsupported file type or size');
  intent.method = 'POST'; intent.path = '/quest/attachments'; intent.body = { session_id: identity, filename: basename(file), media_type: media, data: bytes.toString('base64') };
} else if (['end', 'discard'].includes(action)) {
  intent.method = 'POST'; intent.path = '/sessions/' + identity + '/' + action; intent.body = { operation_id: operation };
} else if (['state', 'summary', 'session'].includes(action)) intent.path = '/quest/sessions/' + identity + (action === 'session' ? '' : '/' + action);
else if (action === 'history') intent.path = '/sessions/' + identity + '/history';
else if (action === 'recover') intent.path = '/requests/' + identity;
else if (action === 'profile') intent.path = '/quest/learners/' + intent.external_user_id + '/profile';
else if (['catalog', 'sessions'].includes(action)) intent.path = '/quest/' + action;
else if (action === 'export') { intent.method = 'POST'; intent.path = '/quest/data/export'; intent.body = {}; }
else if (action === 'export-file') { intent.method = 'POST'; intent.path = '/quest/data/export/attachments/' + identity; intent.body = {}; }
else if (action === 'download') intent.path = '/quest/attachments/' + identity;
else if (action === 'delete-file') { intent.method = 'DELETE'; intent.path = '/quest/attachments/' + identity; intent.body = {}; }
else if (action === 'erase') { intent.method = 'POST'; intent.path = '/data/erase'; intent.body = { operation_id: operation }; }
else throw new Error('Choose setup, guided, feedback, explain, default, opening, upload, end, discard, catalog, sessions, session, state, summary, profile, history, recover, export, export-file, download, delete-file or erase');
if (['guided', 'feedback', 'explain', 'default', 'opening', 'upload', 'end', 'discard', 'state', 'summary', 'session', 'history', 'recover', 'export-file', 'download', 'delete-file'].includes(action)
  && !/^[A-Za-z0-9_-]{1,128}$/.test(identity ?? '')) throw new Error('Supply the returned session, request or attachment identity');
if (intent.method !== 'GET') intent.idempotency_key = operation;
requestOptions(intent, 'synthetic-validation-only');
if (!output) throw new Error('Supply a new output filename');
const target = await open(output, 'wx', 0o600);
try { await target.writeFile(JSON.stringify(intent, null, 2) + '\n'); await target.sync(); } finally { await target.close(); }
console.log('Saved one new intent. Reuse this exact file to recover an uncertain operation.');

// Node 24+, no packages. One saved intent per operation; no automatic retries.
import { readFile, open } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
export interface Intent { base_url: string; assignment_id: string; external_user_id: string;
  method: 'GET' | 'POST' | 'DELETE'; path: string; query?: Record<string, string | number>;
  idempotency_key?: string; body?: Record<string, unknown> }
type Row = Record<string, any>;
const ident = '[A-Za-z0-9_-]{1,128}';
const paths = new RegExp('^/(?:chat|requests/' + ident + '|sessions(?:/' + ident + '(?:/(?:end|discard|history))?)?|session/status|data/(?:export|erase)|quest/(?:catalog|sessions(?:/' + ident + '(?:/(?:state|summary))?)?|attachments(?:/' + ident + ')?|learners/' + ident + '/profile|data/export(?:/attachments/' + ident + ')?))$');
const uuid = /^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/;
export const UPLOAD_BYTES = 4 * Math.ceil(8 * 1024 * 1024 / 3) + 16384;
export function requestOptions(intent: Intent, key: string) {
  const base = new URL(intent.base_url);
  if (base.protocol !== 'https:' || base.username || base.password || base.search || base.hash || !/^\/v1\/?$/.test(base.pathname)
    || !paths.test(intent.path) || !uuid.test(intent.assignment_id) || !/^[\x21-\x7e]{1,512}$/.test(key)
    || typeof intent.external_user_id !== 'string' || !/^[A-Za-z0-9_-]{1,128}$/.test(intent.external_user_id)
    || !['GET', 'POST', 'DELETE'].includes(intent.method)) throw new Error('Invalid saved intent or credentials');
  const url = new URL(base.href.replace(/\/$/, '') + intent.path);
  const headers: Record<string, string> = { Authorization: 'Bearer ' + key, 'X-Assignment-Id': intent.assignment_id,
    'X-User-Id': intent.external_user_id, 'FL-API-Version': '2026-12-01' };
  for (const [name, value] of Object.entries(intent.query ?? {})) {
    if (!['limit', 'cursor', 'session_id'].includes(name)) throw new Error('Unexpected query field');
    url.searchParams.set(name, String(value));
  }
  let body: string | undefined;
  if (intent.method !== 'GET') {
    if (!uuid.test(intent.idempotency_key ?? '')) throw new Error('Save an operation UUID before dispatch');
    headers['Idempotency-Key'] = intent.idempotency_key!; headers['Content-Type'] = 'application/json';
    body = JSON.stringify(intent.body ?? {});
    if (Buffer.byteLength(body) > (intent.path === '/quest/attachments' ? UPLOAD_BYTES : 131072)) throw new Error('Request exceeds the example bound');
  } else if (intent.body !== undefined) throw new Error('GET cannot have a body');
  if (intent.path.startsWith('/quest/learners/') && intent.path !== '/quest/learners/' + intent.external_user_id + '/profile') throw new Error('Profile user mismatch');
  return { url, options: { method: intent.method, headers, body, redirect: 'error' as const } };
}
function questReceipt(q: Row) {
  const keys = ['mode', 'posture', 'composition_hash', 'turn_index', 'team_dialog', 'repairs', 'validation_failures'];
  return q && Object.keys(q).length === keys.length && Object.keys(q).every(k => keys.includes(k))
    && typeof q.mode === 'string' && /^[a-z0-9][a-z0-9-]{0,99}$/.test(q.mode) && ['guided', 'feedback', 'explain', 'diagnostic'].includes(q.posture)
    && typeof q.composition_hash === 'string' && /^[a-f0-9]{64}$/.test(q.composition_hash) && Number.isSafeInteger(q.turn_index) && q.turn_index >= 0 && typeof q.team_dialog === 'boolean'
    && ['repairs', 'validation_failures'].every(k => Array.isArray(q[k]) && q[k].length <= 64 && q[k].every((v: unknown) => typeof v === 'string' && /^[a-z_]+(?::[a-z_]+)?$/.test(v)));
}
function verify(result: Row, requireEnd = false) {
  const s = result.safety_status, c = result.commercial;
  if (!result.request_id || !result.session_id || result.stop_reason !== 'end_turn' || typeof result.session_ended !== 'boolean'
    || requireEnd && !result.session_ended || !questReceipt(result.quest)
    || s?.type !== 'safety_status' || s.schema_version !== 1 || !['unknown', 'clear', 'watch', 'warning', 'critical'].includes(s.level)
    || s.evaluated !== (s.level !== 'unknown') || !['none', 'support', 'escalate'].includes(s.response_action) || !['governed_turn', 'backstop'].includes(s.source)
    || !c || !['listing', 'band', 'rate_version'].every(k => typeof c[k] === 'string' && c[k])
    || ![0, 1].includes(c.billable_units) || !Number.isSafeInteger(c.charge?.amount_micro_usd) || c.charge.amount_micro_usd < 0 || c.charge.currency !== 'USD'
    || !['settled', 'released', 'reserved'].includes(c.settlement) || (c.billable_units === 0 && c.charge.amount_micro_usd !== 0)
    || (c.settlement === 'released' && c.billable_units !== 0) || !Array.isArray(result.parts) || result.parts.length > 4096
    || result.parts.some((p: Row) => !(['conversation', 'display'].includes(p.part) || result.quest.team_dialog && p.part === 'frame') || typeof p.text !== 'string')
    || !['conversation', 'display'].every(part => result.parts.some((p: Row) => p.part === part && p.text.trim()))) throw new Error('Incomplete or unverified Learn result; recover the original request');
  // Project only public fields. Never return unknown events or raw internal carriers.
  return { request_id: result.request_id, session_id: result.session_id, parts: result.parts.map((p: Row) => ({ part: p.part, text: p.text })),
    safety_status: Object.fromEntries(['type', 'schema_version', 'evaluated', 'level', 'response_action', 'source'].map(k => [k, s[k]])), quest: result.quest,
    commercial: { ...Object.fromEntries(['listing', 'band', 'rate_version', 'billable_units', 'settlement'].map(k => [k, c[k]])), charge: { amount_micro_usd: c.charge.amount_micro_usd, currency: c.charge.currency } },
    session_ended: result.session_ended, stop_reason: result.stop_reason };
}
export function parseQuestStream(source: string, requireEnd = false, expectedSession?: string) {
  let request: string | undefined, session: string | undefined, safety: Row | undefined, quest: Row | undefined;
  let ended = false, complete = false, commercial: Row | undefined;
  const parts: { part: string; text: string }[] = [];
  for (const frame of source.replaceAll('\r\n', '\n').split('\n\n')) {
    const data = frame.split('\n').filter(line => line.startsWith('data:')).map(line => line.slice(5).trimStart()).join('\n');
    if (!data) continue;
    const event = JSON.parse(data);
    if (complete || event.type === 'error') throw new Error('Interrupted or invalid stream; recover original request ' + (request ?? ''));
    if (event.type === 'metadata') {
      if (request || typeof event.request_id !== 'string' || typeof event.sessionId !== 'string' || expectedSession && event.sessionId !== expectedSession) throw new Error('Invalid stream identity');
      request = event.request_id; session = event.sessionId;
    } else {
      if (!request) throw new Error('Missing stream identity');
      if (event.type === 'content') parts.push({ part: event.part, text: event.text });
      else if (event.type === 'safety_status') { if (safety) throw new Error('Duplicate safety receipt'); safety = event; }
      else if (event.type === 'quest_receipt') { if (quest) throw new Error('Duplicate Learn receipt'); quest = event.receipt; }
      else if (event.type === 'session_ended') { if (event.sessionId !== session) throw new Error('Invalid closeout identity'); ended = true; }
      else if (event.type === 'done') {
        if (event.sessionId !== session || event.commercial?.request_id !== request || event.stopReason !== 'end_turn') throw new Error('Invalid final identity');
        commercial = event.commercial; complete = true;
      }
    }
  }
  if (!complete) throw new Error('Incomplete stream; recover original request ' + (request ?? ''));
  return verify({ request_id: request, session_id: session, parts, safety_status: safety, quest, commercial, session_ended: ended, stop_reason: 'end_turn' }, requireEnd);
}
export function parseQuestResponse(intent: Intent, source: string, type: string) {
  if (type === 'text/event-stream') return parseQuestStream(source, intent.path.endsWith('/end'), intent.body?.session_id as string | undefined ?? (intent.path.endsWith('/end') ? intent.path.split('/')[2] : undefined));
  if (type !== 'application/json') throw new Error('Unexpected response type');
  const data = JSON.parse(source);
  if (intent.path.startsWith('/requests/')) {
    if (data.request_id !== intent.path.split('/')[2] || !['committed', 'in_progress', 'unavailable'].includes(data.status)) throw new Error('Invalid recovery identity');
    if (data.status === 'committed') return { status: data.status, ...verify({ ...data.result, request_id: data.request_id, session_id: data.session_id }) };
    if (data.result !== undefined) throw new Error('Uncommitted result');
    return { status: data.status, request_id: data.request_id, session_id: data.session_id };
  }
  if (intent.path === '/chat' || intent.path.endsWith('/end')) throw new Error('Generation requires a verified stream');
  if (data.operation_id !== undefined && intent.body?.operation_id !== undefined && data.operation_id !== intent.body.operation_id) throw new Error('Mismatched operation receipt');
  return data;
}
export async function execute(intent: Intent, key: string, fetcher: typeof fetch = fetch) {
  const { url, options } = requestOptions(intent, key);
  const response = await fetcher(url, { ...options, signal: AbortSignal.timeout(120000) });
  if (!response.body) throw new Error('Missing response; recover the original request');
  const reader = response.body.getReader(), chunks: Uint8Array[] = []; let length = 0;
  try { for (;;) { const { done, value } = await reader.read(); if (done) break; length += value.length;
    if (length > (response.ok ? 8 * 1024 * 1024 : 32768)) { await reader.cancel(); throw new Error('Response exceeds bound'); } chunks.push(value); } }
  finally { reader.releaseLock(); }
  const bytes = Buffer.concat(chunks), type = response.headers.get('content-type')?.split(';')[0].trim() ?? '';
  if (!response.ok) throw new Error('HTTP ' + response.status + '; recover original request ' + (response.headers.get('x-request-id') ?? '') + '; keep the saved body and operation identity');
  if (['image/png', 'image/jpeg', 'image/webp', 'text/plain', 'text/markdown'].includes(type)
    && ((intent.method === 'GET' && /^\/quest\/attachments\/[^/]+$/.test(intent.path))
      || (intent.method === 'POST' && /^\/quest\/data\/export\/attachments\/[^/]+$/.test(intent.path)))) return { bytes, status: response.status };
  return { data: parseQuestResponse(intent, new TextDecoder('utf-8', { fatal: true }).decode(bytes), type), status: response.status };
}
async function main() {
  const [input, output] = process.argv.slice(2); if (!input || !output) throw new Error('node quest.ts saved-intent.json new-response.json (or .bin)');
  const bytes = await readFile(input); if (bytes.length > UPLOAD_BYTES + 4096) throw new Error('Saved intent too large');
  const intent = JSON.parse(bytes.toString('utf8')), target = await open(output, 'wx', 0o600);
  try { const result = await execute(intent, process.env.FOREVERLEARNING_API_KEY ?? '');
    await target.writeFile('bytes' in result ? result.bytes! : JSON.stringify(result, null, 2) + '\n'); await target.sync();
  } finally { await target.close(); }
  console.log('Saved response. Check status and completion before another operation.');
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main().catch(error => { console.error(error.message); process.exitCode = 1; });

"""Python 3.11+, standard library. One saved operation, no automatic retries.
python quest.py saved-intent.json new-response.json
python quest.py --curl saved-intent.json new-response.json  # uses installed curl
"""
import json
import os
import re
import subprocess
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request

IDENT = r"[A-Za-z0-9_-]{1,128}"
PATH = re.compile(r"^/(?:chat|requests/" + IDENT + r"|sessions(?:/" + IDENT + r"(?:/(?:end|discard|history))?)?|session/status|data/(?:export|erase)|quest/(?:catalog|sessions(?:/" + IDENT + r"(?:/(?:state|summary))?)?|attachments(?:/" + IDENT + r")?|learners/" + IDENT + r"/profile|data/export(?:/attachments/" + IDENT + r")?))$")
UUID = re.compile(r"^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$")
UPLOAD_BYTES = 4 * ((8 * 1024 * 1024 + 2) // 3) + 16384
BOUND = 8 * 1024 * 1024


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise ValueError("Redirect refused; verify the assigned API host")


def make_request(intent, key):
    base = urllib.parse.urlsplit(intent["base_url"])
    user, method, path = intent["external_user_id"], intent["method"], intent["path"]
    if (base.scheme != "https" or not base.netloc or base.username or base.password or base.query or base.fragment
            or base.path not in ("/v1", "/v1/") or not PATH.fullmatch(path)
            or not UUID.fullmatch(intent["assignment_id"]) or not re.fullmatch(IDENT, user)
            or not re.fullmatch(r"[\x21-\x7e]{1,512}", key) or method not in ("GET", "POST", "DELETE")):
        raise ValueError("Invalid saved intent or credentials")
    query = intent.get("query", {})
    if any(name not in ("limit", "cursor", "session_id") for name in query):
        raise ValueError("Unexpected query field")
    if path.startswith("/quest/learners/") and path != "/quest/learners/" + user + "/profile":
        raise ValueError("Profile user mismatch")
    url = intent["base_url"].rstrip("/") + path + (("?" + urllib.parse.urlencode(query)) if query else "")
    # Name the client. urllib's default name is refused by hosts that screen clients by their signature.
    headers = {"Authorization": "Bearer " + key, "X-Assignment-Id": intent["assignment_id"], "X-User-Id": user, "FL-API-Version": "2026-12-01",
               "User-Agent": "foreverlearning-learn-example/1.0 (python)"}
    body = None
    if method != "GET":
        if not UUID.fullmatch(intent.get("idempotency_key", "")):
            raise ValueError("Save an operation UUID before dispatch")
        headers.update({"Idempotency-Key": intent["idempotency_key"], "Content-Type": "application/json"})
        body = json.dumps(intent.get("body", {}), ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        if len(body) > (UPLOAD_BYTES if path == "/quest/attachments" else 131072):
            raise ValueError("Request exceeds bound")
    elif "body" in intent:
        raise ValueError("GET cannot have a body")
    return url, method, headers, body


def verify(value, require_end=False):
    q, s, c = value.get("quest", {}), value.get("safety_status", {}), value.get("commercial", {})
    parts = value.get("parts", [])
    charge = c.get("charge", {})
    if (not value.get("request_id") or not value.get("session_id") or value.get("stop_reason") != "end_turn"
            or type(value.get("session_ended")) is not bool or require_end and not value["session_ended"]
            or set(q) != {"mode", "posture", "composition_hash", "turn_index", "team_dialog", "repairs", "validation_failures"}
            or not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,99}", q.get("mode", ""))
            or q.get("posture") not in ("guided", "feedback", "explain", "diagnostic") or not re.fullmatch(r"[a-f0-9]{64}", q.get("composition_hash", ""))
            or type(q.get("turn_index")) is not int or not 0 <= q["turn_index"] <= 9007199254740991 or type(q.get("team_dialog")) is not bool
            or any(not isinstance(q.get(k), list) or len(q[k]) > 64 or any(not isinstance(v, str) or not re.fullmatch(r"[a-z_]+(?::[a-z_]+)?", v) for v in q[k]) for k in ("repairs", "validation_failures"))
            or s.get("type") != "safety_status" or s.get("schema_version") != 1 or s.get("level") not in ("unknown", "clear", "watch", "warning", "critical")
            or type(s.get("evaluated")) is not bool or s["evaluated"] != (s["level"] != "unknown") or s.get("response_action") not in ("none", "support", "escalate") or s.get("source") not in ("governed_turn", "backstop")
            or any(not isinstance(c.get(k), str) or not c[k] for k in ("listing", "band", "rate_version"))
            or type(c.get("billable_units")) is not int or c["billable_units"] not in (0, 1)
            or type(charge.get("amount_micro_usd")) is not int or not 0 <= charge["amount_micro_usd"] <= 9007199254740991 or charge.get("currency") != "USD"
            or c.get("settlement") not in ("reserved", "settled", "released") or (c["billable_units"] == 0 and charge["amount_micro_usd"] != 0)
            or c["settlement"] == "released" and c["billable_units"] != 0 or not isinstance(parts, list) or len(parts) > 4096
            or any(p.get("part") not in (("conversation", "display", "frame") if q["team_dialog"] else ("conversation", "display")) or not isinstance(p.get("text"), str) for p in parts)
            or any(not any(p["part"] == name and p["text"].strip() for p in parts) for name in ("conversation", "display"))):
        raise ValueError("Incomplete or unverified Learn result; recover the original request")
    return {"request_id": value["request_id"], "session_id": value["session_id"], "parts": [{"part": p["part"], "text": p["text"]} for p in parts],
            "quest": q, "safety_status": {k: s[k] for k in ("type", "schema_version", "evaluated", "level", "response_action", "source")},
            "commercial": {**{k: c[k] for k in ("listing", "band", "rate_version", "billable_units", "settlement")}, "charge": {k: charge[k] for k in ("amount_micro_usd", "currency")}},
            "session_ended": value["session_ended"], "stop_reason": "end_turn"}


def parse_stream(source, require_end=False, expected_session=None):
    request_id = session_id = safety = quest = commercial = None
    ended = complete = False
    parts = []
    for frame in source.replace("\r\n", "\n").split("\n\n"):
        data = "\n".join(line[5:].lstrip() for line in frame.split("\n") if line.startswith("data:"))
        if not data:
            continue
        event = json.loads(data)
        kind = event.get("type")
        if complete or kind == "error":
            raise ValueError("Interrupted or invalid stream; recover original request " + (request_id or ""))
        if kind == "metadata":
            if request_id or not isinstance(event.get("request_id"), str) or not isinstance(event.get("sessionId"), str) or expected_session and event["sessionId"] != expected_session:
                raise ValueError("Invalid stream identity")
            request_id, session_id = event["request_id"], event["sessionId"]
        else:
            if not request_id:
                raise ValueError("Missing stream identity")
            if kind == "content":
                parts.append({"part": event.get("part"), "text": event.get("text")})
            elif kind == "safety_status":
                if safety:
                    raise ValueError("Duplicate safety receipt")
                safety = event
            elif kind == "quest_receipt":
                if quest:
                    raise ValueError("Duplicate Learn receipt")
                quest = event.get("receipt")
            elif kind == "session_ended":
                if event.get("sessionId") != session_id:
                    raise ValueError("Invalid closeout identity")
                ended = True
            elif kind == "done":
                if event.get("sessionId") != session_id or event.get("commercial", {}).get("request_id") != request_id or event.get("stopReason") != "end_turn":
                    raise ValueError("Invalid final identity")
                commercial, complete = event["commercial"], True
    if not complete:
        raise ValueError("Incomplete stream; recover original request " + (request_id or ""))
    return verify({"request_id": request_id, "session_id": session_id, "parts": parts, "safety_status": safety or {}, "quest": quest or {}, "commercial": commercial or {}, "session_ended": ended, "stop_reason": "end_turn"}, require_end)


def parse_response(intent, source, media):
    path = intent["path"]
    if media == "text/event-stream":
        return parse_stream(source, path.endswith("/end"), intent.get("body", {}).get("session_id") or (path.split("/")[2] if path.endswith("/end") else None))
    if media != "application/json":
        raise ValueError("Unexpected response type")
    data = json.loads(source)
    if path.startswith("/requests/"):
        if data.get("request_id") != path.split("/")[2] or data.get("status") not in ("committed", "in_progress", "unavailable"):
            raise ValueError("Invalid recovery identity")
        if data["status"] == "committed":
            return {"status": data["status"], **verify({**data.get("result", {}), "request_id": data["request_id"], "session_id": data.get("session_id")})}
        if "result" in data:
            raise ValueError("Uncommitted result")
        return {k: data.get(k) for k in ("status", "request_id", "session_id")}
    if path == "/chat" or path.endswith("/end"):
        raise ValueError("Generation requires a verified stream")
    if "operation_id" in data and "operation_id" in intent.get("body", {}) and data["operation_id"] != intent["body"]["operation_id"]:
        raise ValueError("Mismatched operation receipt")
    return data


def transport(intent, key, use_curl=False):
    url, method, headers, body = make_request(intent, key)
    if use_curl:
        # Secret headers never appear in argv. Temporary private files are removed on exit.
        with tempfile.TemporaryDirectory(prefix="quest-example-") as directory:
            header_file, body_file, output = [os.path.join(directory, x) for x in ("headers", "body", "response")]
            with open(header_file, "x", encoding="utf-8") as stream:
                os.chmod(header_file, 0o600)
                stream.write("".join(k + ": " + v + "\n" for k, v in headers.items()))
            args = ["curl", "--silent", "--show-error", "--proto", "=https", "--max-time", "120", "--max-filesize", str(BOUND),
                    "--request", method, "--header", "@" + header_file, "--output", output, "--write-out", "%{http_code}\n%{content_type}"]
            if body is not None:
                with open(body_file, "xb") as stream:
                    os.chmod(body_file, 0o600)
                    stream.write(body)
                args += ["--data-binary", "@" + body_file]
            done = subprocess.run(args + ["--url", url], check=True, capture_output=True, text=True, timeout=125)
            status, media = done.stdout.split("\n", 1)
            with open(output, "rb") as stream:
                data = stream.read(BOUND + 1)
            return int(status), media.split(";")[0].strip(), data
    opener = urllib.request.build_opener(NoRedirect())
    request = urllib.request.Request(url, data=body, headers=headers, method=method)
    try:
        response = opener.open(request, timeout=120)
    except urllib.error.HTTPError as error:
        response = error
    with response:
        return response.status, response.headers.get_content_type(), response.read(BOUND + 1)


def main():
    args = sys.argv[1:]
    use_curl = args and args[0] == "--curl"
    if use_curl:
        args = args[1:]
    if len(args) != 2:
        raise ValueError("python quest.py [--curl] saved-intent.json new-response.json (or .bin)")
    with open(args[0], "rb") as source:
        saved = source.read(UPLOAD_BYTES + 4097)
    if len(saved) > UPLOAD_BYTES + 4096:
        raise ValueError("Saved intent too large")
    intent = json.loads(saved)
    with open(args[1], "xb") as output:
        os.chmod(args[1], 0o600)
        status, media, data = transport(intent, os.environ.get("FOREVERLEARNING_API_KEY", ""), use_curl)
        if len(data) > BOUND:
            raise ValueError("Response exceeds bound")
        if not 200 <= status < 300:
            raise ValueError("HTTP " + str(status) + "; retain the original body and operation identity")
        binary_path = ((intent["method"] == "GET" and re.fullmatch(r"/quest/attachments/[^/]+", intent["path"]))
                       or (intent["method"] == "POST" and re.fullmatch(r"/quest/data/export/attachments/[^/]+", intent["path"])))
        if binary_path and media in ("image/png", "image/jpeg", "image/webp", "text/plain", "text/markdown"):
            output.write(data)
        else:
            output.write((json.dumps({"status": status, "data": parse_response(intent, data.decode("utf-8"), media)}, indent=2) + "\n").encode("utf-8"))
        output.flush()
        os.fsync(output.fileno())
    print("Saved response. Check status and completion before another operation.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        print("Request not confirmed. Retain the saved intent; inspect the original request before continuing.", file=sys.stderr)
        sys.exit(1)

// Node 24+: node server.ts saved-intent.json new-response-directory
// Local browser -> your backend -> Learn. Loopback demonstration of one saved intent.
// A hosted application must supply its own authenticated user, tenancy and durable operation store.
import { createServer } from 'node:http';
import { readFile, mkdir, open } from 'node:fs/promises';
import { join } from 'node:path';
import { randomBytes, randomUUID } from 'node:crypto';
import { execute, requestOptions, UPLOAD_BYTES } from './quest.ts';
const [input, directory] = process.argv.slice(2);
if (!input || !directory) throw new Error('node server.ts saved-intent.json new-response-directory');
const bytes = await readFile(input);
if (bytes.length > UPLOAD_BYTES + 4096) throw new Error('Saved intent too large');
const intent = JSON.parse(bytes.toString('utf8')), key = process.env.FOREVERLEARNING_API_KEY ?? '';
requestOptions(intent, key); await mkdir(directory, { mode: 0o700 });
const token = randomBytes(32).toString('hex'), host = '127.0.0.1:4317', origin = 'http://' + host;
let busy = false;
const server = createServer(async (request, response) => {
  response.setHeader('Cache-Control', 'no-store'); response.setHeader('X-Content-Type-Options', 'nosniff');
  response.setHeader('Content-Security-Policy', "default-src 'none'; script-src 'nonce-" + token + "'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'");
  if (request.headers.host !== host) { response.writeHead(403).end(); return; }
  if (request.method === 'GET' && request.url === '/') {
    response.setHeader('Content-Type', 'text/html; charset=utf-8');
    response.end(`<!doctype html><html lang="en"><meta charset="utf-8"><title>Learn backend example</title><h1>Run the saved Learn request</h1><p>This uses the operation already saved on your server. A repeat uses the same identity and body.</p><button id="run">Send saved request</button><pre id="result" role="status"></pre><script nonce="${token}">const button=document.querySelector('#run'),out=document.querySelector('#result');button.onclick=async()=>{button.disabled=true;out.textContent='Waiting for confirmed completion…';try{const reply=await fetch('/run',{method:'POST',headers:{'X-Local-Request':'${token}'}});out.textContent=await reply.text();}catch{out.textContent='Connection interrupted. Check the same saved request.';}finally{button.disabled=false;}};</script></html>`); return;
  }
  if (request.method !== 'POST' || request.url !== '/run' || request.headers.origin !== origin || request.headers['x-local-request'] !== token
    || request.headers['transfer-encoding'] || Number(request.headers['content-length'] ?? 0) !== 0) { response.writeHead(403).end(); return; }
  if (busy) { response.writeHead(409).end('The original operation is still running.'); return; }
  busy = true;
  try {
    const file = await open(join(directory, randomUUID() + '.json'), 'wx', 0o600);
    try { const result = await execute(intent, key); if ('bytes' in result) throw new Error('Use the CLI for binary downloads');
      await file.writeFile(JSON.stringify(result, null, 2) + '\n'); await file.sync();
      response.setHeader('Content-Type', 'application/json'); response.end(JSON.stringify(result.data));
    } finally { await file.close(); }
  } catch { response.writeHead(502).end('Request not confirmed. Recover the same saved request before creating another operation.'); }
  finally { busy = false; }
});
server.listen(4317, '127.0.0.1', () => console.log('Open ' + origin + '. The server holds the key and saved operation.'));

