files.03-photos-of-work/server.ts:
// Photos of handwritten work: the learner attaches photos of their page (up to four) and gets
// help on their own lines. Builds on step 2's four kinds of help. A small server that keeps
// the Learn key and a chat page that shows the reply. Node 24+, no packages. npm start
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFile, appendFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { join } from 'node:path';
import { createSession, sendTurn, uploadAttachment, isConfigured, LearnError } from './learn.ts';

const PORT = Number(process.env.PORT ?? 3000);
const PUBLIC = join(import.meta.dirname, 'public');
const RECEIPTS = join(import.meta.dirname, 'receipts.jsonl');

// One Learn session per learner. A real app keeps this in its database.
const sessions = new Map<string, { id: string; diagnostic: boolean }>();

// The task for teaching sessions (Guided, Feedback, Explain): practice, so all three fit.
const SETUP = { task: { kind: 'practice', subject: 'Algebra' }, team_dialog: false };
// A Diagnostic session: the posture and the learner's finished work are set when it is prepared.
function diagnosticSetup(finishedWork: string) {
  return {
    task: { kind: 'practice', subject: 'Algebra', assignment: 'A finished practice quiz.' },
    posture: 'diagnostic',
    // The finished work can only be given here, when the session is prepared.
    assessment: {
      schema_version: 'fl.quest.assessment-input.v1',
      goal: 'Find what the learner understands from their finished practice quiz.',
      sources: [{ id: 'quiz', origin: 'submitted_work', text: finishedWork, attachment_id: null, locator: 'finished quiz', availability: 'available' }],
      items: [], targets: [], original_result: '', limitations: [],
    },
    team_dialog: false,
  };
}

const FILES: Record<string, string> = {
  '/': 'index.html',
  '/app.js': 'app.js',
  '/style.css': 'style.css',
};
const TYPES: Record<string, string> = { html: 'text/html; charset=utf-8', js: 'text/javascript; charset=utf-8', css: 'text/css; charset=utf-8' };

// A pseudonymous learner id kept in a cookie: never a name or an email.
function learnerId(request: IncomingMessage, response: ServerResponse): string {
  const match = /(?:^|;\s*)learner=([A-Za-z0-9_-]{1,128})/.exec(request.headers.cookie ?? '');
  if (match) return match[1];
  const id = 'learner-' + randomUUID();
  response.setHeader('Set-Cookie', 'learner=' + id + '; Path=/; HttpOnly; SameSite=Strict; Max-Age=31536000');
  return id;
}

async function readJson(request: IncomingMessage, limit = 20000): Promise<Record<string, unknown>> {
  let raw = '';
  for await (const chunk of request) {
    raw += chunk;
    if (raw.length > limit) throw new Error('Message too long');
  }
  return JSON.parse(raw || '{}');
}

// What the learner sees when a request fails: your app's own short words. Learn's own message is
// for you, in the server log with the request id; never show it to the learner.
function forLearner(e: LearnError): string {
  if (e.code === 'DEVELOPER_POLICY_BLOCKED') return "I can't help with that message. Try asking another way.";
  if (e.status === 429) return 'The tutor is busy right now. Try again in a moment.';
  return "That didn't go through. Try again in a moment.";
}

function send(response: ServerResponse, event: string, data: unknown) {
  response.write('event: ' + event + '\ndata: ' + JSON.stringify(data) + '\n\n');
}

// The learner's teaching session (Guided, Feedback, Explain), prepared the first time.
async function teachingSession(learner: string) {
  let session = sessions.get(learner);
  if (!session || session.diagnostic) {
    session = { id: await createSession(learner, SETUP), diagnostic: false };
    sessions.set(learner, session);
  }
  return session;
}

const IMAGE_TYPES = ['image/png', 'image/jpeg', 'image/webp'];

// A photo of the learner's work: uploaded to Learn before the turn that uses it. Free.
async function upload(request: IncomingMessage, response: ServerResponse) {
  const learner = learnerId(request, response);
  const { media_type, data, filename } = await readJson(request, 12_000_000);
  if (typeof media_type !== 'string' || !IMAGE_TYPES.includes(media_type) || typeof data !== 'string' || !data || data.length > 11_184_812) {
    response.writeHead(400, { 'Content-Type': 'application/json' }).end(JSON.stringify({ error: 'Attach a PNG, JPEG or WebP photo up to 8 MiB.' }));
    return;
  }
  try {
    const session = await teachingSession(learner);
    const id = await uploadAttachment(learner, session.id, media_type, data, typeof filename === 'string' ? filename.slice(0, 120) : 'work');
    response.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({ attachment_id: id }));
  } catch (error) {
    const e = error instanceof LearnError ? error : new LearnError(500, 'SERVER_ERROR', (error as Error).message);
    console.error('Upload failed:', e.status, e.code, e.message, e.requestId ? 'request ' + e.requestId : '');
    response.writeHead(e.status >= 400 && e.status < 600 ? e.status : 502, { 'Content-Type': 'application/json' }).end(JSON.stringify({ error: forLearner(e), code: e.code }));
  }
}

const KINDS = ['guided', 'feedback', 'explain', 'diagnostic'] as const;
type Kind = typeof KINDS[number];

async function turn(request: IncomingMessage, response: ServerResponse) {
  const learner = learnerId(request, response);
  const { message, kind, attachment_ids } = await readJson(request);
  const attachmentIds = Array.isArray(attachment_ids) ? attachment_ids.filter((a): a is string => typeof a === 'string').slice(0, 4) : [];
  if (typeof message !== 'string' || !message.trim() || !KINDS.includes(kind as Kind)) {
    response.writeHead(400, { 'Content-Type': 'application/json' }).end(JSON.stringify({ error: 'Choose a kind of help and type a message first.' }));
    return;
  }
  response.writeHead(200, { 'Content-Type': 'text/event-stream; charset=utf-8', 'Cache-Control': 'no-store' });
  try {
    // Guided, Feedback and Explain share one session: the posture goes with each turn.
    // Diagnostic is chosen when the session is prepared, with the finished work, so it gets a
    // session of its own; later Diagnostic messages are the learner's answers, sent with no posture.
    // Starting either kind of session closes the learner's other open one (its closeout is a turn).
    const diagnostic = kind === 'diagnostic';
    let session = sessions.get(learner);
    let opening = false;
    if (!session || session.diagnostic !== diagnostic) {
      // Diagnostic: the learner's finished quiz goes into the session's setup, then the session opens.
      const setup = diagnostic ? diagnosticSetup(message.trim()) : SETUP;
      session = { id: await createSession(learner, setup), diagnostic };
      opening = diagnostic;
      sessions.set(learner, session);
    }
    const posture = diagnostic ? null : kind as 'guided' | 'feedback' | 'explain';
    // Photos go with teaching turns; they belong to the session they were uploaded to.
    const result = await sendTurn(learner, { sessionId: session.id, prompt: opening ? '' : message.trim(), posture, operation: opening ? 'opening' : 'turn', attachmentIds: diagnostic ? [] : attachmentIds }, (part, text) => send(response, 'text', { part, text }));
    // Keep the receipt: one line per confirmed turn.
    await appendFile(RECEIPTS, JSON.stringify({ at: new Date().toISOString(), learner_id: learner, ...result.receipt }) + '\n');
    send(response, 'done', { safety: result.safety, receipt: result.receipt });
  } catch (error) {
    const e = error instanceof LearnError ? error : new LearnError(500, 'SERVER_ERROR', (error as Error).message);
    console.error('Learn turn failed:', e.status, e.code, e.message, e.requestId ? 'request ' + e.requestId : '');
    send(response, 'failed', { status: e.status, code: e.code, message: forLearner(e), request_id: e.requestId });
  }
  response.end();
}

const server = createServer(async (request, response) => {
  response.setHeader('X-Content-Type-Options', 'nosniff');
  try {
    if (request.method === 'POST' && request.url === '/api/turn') return await turn(request, response);
    if (request.method === 'POST' && request.url === '/api/upload') return await upload(request, response);
    const file = request.method === 'GET' ? FILES[(request.url ?? '/').split('?')[0]] : undefined;
    if (!file) {
      response.writeHead(404).end('Not found');
      return;
    }
    learnerId(request, response);
    const body = await readFile(join(PUBLIC, file));
    response.writeHead(200, { 'Content-Type': TYPES[file.split('.').pop()!], 'Cache-Control': 'no-store' }).end(body);
  } catch (error) {
    if (!response.headersSent) response.writeHead(500).end('Server error');
    console.error(error);
  }
});

if (!isConfigured()) console.warn('FOREVERLEARNING_API_KEY is not set. Copy .env.example to .env and add your key.');
server.listen(PORT, '127.0.0.1', () => console.log('Your tutor is running at http://localhost:' + PORT));

files.04-remember-the-learner/learn.ts:
// A small Learn API client for your server. The key is read from the environment
// and never leaves this process. Guide: https://developers.foreverlearning.ai/docs/learn/
import { randomUUID } from 'node:crypto';

const API_VERSION = '2026-12-01';

export type Posture = 'guided' | 'feedback' | 'explain';

export interface SafetyStatus {
  level: 'unknown' | 'clear' | 'watch' | 'warning' | 'critical';
  evaluated: boolean;
  response_action: 'none' | 'support' | 'escalate';
  source: string;
}

export interface Receipt {
  request_id: string;
  session_id: string;
  posture: string;
  turn_index: number;
  billable_units: number;
  charge_micro_usd: number;
  settlement: string;
  safety_level: string;
}

export interface TurnResult {
  request_id: string;
  session_id: string;
  reply: string;
  display: string;
  safety: SafetyStatus;
  receipt: Receipt;
}

export class LearnError extends Error {
  status: number;
  code: string;
  requestId: string;
  constructor(status: number, code: string, message: string, requestId = '') {
    super(message);
    this.status = status;
    this.code = code;
    this.requestId = requestId;
  }
}

function settings() {
  const key = process.env.FOREVERLEARNING_API_KEY ?? '';
  const base = (process.env.FOREVERLEARNING_BASE_URL ?? 'https://developers-api.foreverlearning.ai/v1').replace(/\/+$/, '');
  const assignment = process.env.FOREVERLEARNING_ASSIGNMENT_ID ?? '';
  return { key, base, assignment };
}

export function isConfigured(): boolean {
  return settings().key.length > 0;
}

function headers(learnerId: string, idempotencyKey?: string): Record<string, string> {
  const { key, assignment } = settings();
  const h: Record<string, string> = {
    Authorization: 'Bearer ' + key,
    'X-User-Id': learnerId,
    'FL-API-Version': API_VERSION,
  };
  if (assignment) h['X-Assignment-Id'] = assignment;
  if (idempotencyKey) {
    h['Idempotency-Key'] = idempotencyKey;
    h['Content-Type'] = 'application/json';
  }
  return h;
}

async function failure(response: Response): Promise<LearnError> {
  let code = 'HTTP_' + response.status;
  let message = 'Learn returned HTTP ' + response.status + '.';
  let requestId = response.headers.get('x-request-id') ?? '';
  try {
    const body = await response.json() as { code?: string; message?: string; request_id?: string };
    if (body.code) code = body.code;
    if (body.message) message = body.message;
    if (body.request_id) requestId = body.request_id;
  } catch { /* keep the HTTP status */ }
  return new LearnError(response.status, code, message, requestId);
}

// Prepare a session. No reply is generated and nothing is charged.
export async function createSession(learnerId: string, setup: Record<string, unknown>): Promise<string> {
  const { base } = settings();
  const response = await fetch(base + '/quest/sessions', {
    method: 'POST',
    headers: headers(learnerId, randomUUID()),
    body: JSON.stringify({ setup }),
  });
  if (!response.ok) throw await failure(response);
  const session = await response.json() as { session_id?: string };
  if (!session.session_id) throw new LearnError(502, 'NO_SESSION', 'Learn did not return a session id.');
  return session.session_id;
}

export interface TurnInput {
  sessionId: string;
  prompt: string;
  // Send the posture on every turn: leaving it out means Guided, except in a Diagnostic
  // session, where null leaves it out so the session stays Diagnostic.
  posture?: Posture | null;
  // 'opening' asks Learn to greet the learner, with an empty prompt. It is a turn like any other.
  operation?: 'turn' | 'opening';
  // Up to four uploaded files (photos of the learner's work) for this turn.
  attachmentIds?: string[];
}

// Upload one file of the learner's work. Free: no reply is generated. The returned id is
// private to this learner and session, and goes with a turn in quest.attachment_ids.
export async function uploadAttachment(learnerId: string, sessionId: string, mediaType: string, base64: string, filename: string): Promise<string> {
  const { base } = settings();
  const response = await fetch(base + '/quest/attachments', {
    method: 'POST',
    headers: headers(learnerId, randomUUID()),
    body: JSON.stringify({ session_id: sessionId, media_type: mediaType, data: base64, filename }),
  });
  if (!response.ok) throw await failure(response);
  const upload = await response.json() as { attachment_id?: string };
  if (!upload.attachment_id) throw new LearnError(502, 'NO_ATTACHMENT', 'Learn did not return an attachment id.');
  return upload.attachment_id;
}

// Send one learner turn and pass on the reply when it arrives. onText receives each part of the
// reply: the "conversation" part (what the tutor says) and the
// "display" part (the hint or working to show, in Markdown). The result is returned
// only after Learn's final "done" event confirms the turn, with its safety status
// and receipt.
export async function sendTurn(
  learnerId: string,
  input: TurnInput,
  onText: (part: 'conversation' | 'display', text: string) => void,
): Promise<TurnResult> {
  const { base } = settings();
  const body = {
    session_id: input.sessionId,
    prompt: input.operation === 'opening' ? '' : input.prompt,
    ...(input.posture === null ? {} : { posture: input.posture ?? 'guided' }),
    quest: {
      operation: input.operation ?? 'turn', requested_support: 'auto', team_dialog: false,
      ...(input.attachmentIds?.length ? { attachment_ids: input.attachmentIds } : {}),
    },
  };
  const response = await fetch(base + '/chat', {
    method: 'POST',
    headers: headers(learnerId, randomUUID()),
    body: JSON.stringify(body),
  });
  return readTurn(response, input.sessionId, onText, false);
}

// End a session when the learner finishes. Learn writes and saves the session's summary
// and what it learned about the learner; the closeout is a turn like any other.
export async function endSession(
  learnerId: string,
  sessionId: string,
  onText: (part: 'conversation' | 'display', text: string) => void,
): Promise<TurnResult> {
  const { base } = settings();
  const operation = randomUUID(); // the same value is the operation id and the Idempotency-Key
  const response = await fetch(base + '/sessions/' + encodeURIComponent(sessionId) + '/end', {
    method: 'POST',
    headers: headers(learnerId, operation),
    body: JSON.stringify({ operation_id: operation }),
  });
  return readTurn(response, sessionId, onText, true);
}

// Free saved reads: a session's summary and state, and the learner's profile.
export async function getSaved(learnerId: string, path: string): Promise<Record<string, any>> {
  const { base } = settings();
  const response = await fetch(base + path, { headers: headers(learnerId) });
  if (!response.ok) throw await failure(response);
  return await response.json() as Record<string, any>;
}

async function readTurn(
  response: Response,
  expectedSession: string,
  onText: (part: 'conversation' | 'display', text: string) => void,
  requireEnd: boolean,
): Promise<TurnResult> {
  if (!response.ok || !response.body) throw await failure(response);
  const input = { sessionId: expectedSession };
  let ended = false;

  let requestId = '';
  let sessionId = '';
  let reply = '';
  let display = '';
  let safety: SafetyStatus | undefined;
  let questReceipt: Record<string, unknown> | undefined;
  let commercial: Record<string, any> | undefined;

  const handle = (event: Record<string, any>) => {
    switch (event.type) {
      case 'metadata':
        requestId = event.request_id;
        sessionId = event.sessionId;
        break;
      case 'content':
        if (event.part === 'conversation') {
          reply += event.text;
          onText('conversation', event.text);
        } else if (event.part === 'display') {
          display += event.text;
          onText('display', event.text);
        }
        break;
      case 'safety_status':
        safety = event as SafetyStatus;
        break;
      case 'quest_receipt':
        questReceipt = event.receipt;
        break;
      case 'done':
        commercial = event.commercial;
        break;
      case 'session_ended':
        ended = event.sessionId === sessionId;
        break;
      case 'error':
        throw new LearnError(502, event.code ?? 'STREAM_ERROR', event.message ?? 'The turn did not complete.', event.request_id ?? requestId);
      default:
        break; // Unknown future events are ignored, never treated as success.
    }
  };

  const decoder = new TextDecoder();
  const reader = response.body.getReader();
  let buffer = '';
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true }).replaceAll('\r\n', '\n');
    let end: number;
    while ((end = buffer.indexOf('\n\n')) >= 0) {
      const frame = buffer.slice(0, end);
      buffer = buffer.slice(end + 2);
      const data = frame.split('\n').filter((line) => line.startsWith('data:')).map((line) => line.slice(5).trimStart()).join('\n');
      if (data) handle(JSON.parse(data));
    }
  }

  // A reply is committed only when the final event arrived with the same identity.
  if (!commercial || commercial.request_id !== requestId || !safety || !questReceipt) {
    throw new LearnError(502, 'INCOMPLETE', 'The turn was not confirmed. Look it up with GET /v1/requests/' + requestId + ', as the same learner (X-User-Id), before sending again.', requestId);
  }
  if (sessionId !== input.sessionId) throw new LearnError(502, 'SESSION_MISMATCH', 'The reply belongs to a different session.', requestId);
  if (requireEnd && !ended) throw new LearnError(502, 'NOT_ENDED', 'The closeout was not confirmed. Look it up with GET /v1/requests/' + requestId + ', as the same learner (X-User-Id).', requestId);

  return {
    request_id: requestId,
    session_id: sessionId,
    reply,
    display,
    safety,
    receipt: {
      request_id: requestId,
      session_id: sessionId,
      posture: String(questReceipt.posture),
      turn_index: Number(questReceipt.turn_index),
      billable_units: Number(commercial.billable_units),
      charge_micro_usd: Number(commercial.charge?.amount_micro_usd ?? 0),
      settlement: String(commercial.settlement),
      safety_level: safety.level,
    },
  };
}

